void lm_powered_trig_input(apollo_overlay_state *m,agc_word *irq,uint16_t n,uint8_t live){uint32_t seed=UINT32_C(0x35073515)+((uint32_t)n>>8)*UINT32_C(0x9e3779b9)+live;unsigned i;for(i=0;i<2048u;++i){seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;m->words[i]=(agc_word)(seed&AGC_MASK);}m->words[0]=n;m->words[1]=(agc_word)((uint32_t)n*37u);m->words[2]=(agc_word)(02000u+n%3072u);m->words[3]=(agc_word)(((n/32u)%8u)<<8);m->words[4]=046000;m->words[5]=live?03547:03555;m->words[6]=(agc_word)(046000u|(m->words[3]>>8));m->words[7]=0;m->words[023]=0;m->words[067]=(agc_word)((n&1u)?1u:077777u);m->words[0163]=n;for(i=0;i<3u;++i){m->words[032u+i]=(agc_word)(((uint32_t)n*(2u*i+1u)+43u*i)&AGC_MASK);m->words[0766u+2u*i]=(agc_word)(((uint32_t)n*(2u*i+3u)+17u*i)&AGC_MASK);}*irq=(agc_word)(n&1u);}
